import{c as a,Z as o,Q as t,j as e,m as r,o as s}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"采薇","description":"","frontmatter":{"title":"采薇","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/5.md","filePath":"books/shici/shijing/5.md"}'),n={name:"books/shici/shijing/5.md"};function h(u,i,c,d,q,p){const l=o("PoemNav");return t(),e("div",null,[i[0]||(i[0]=r('<h1 id="采薇" tabindex="-1">采薇 <a class="header-anchor" href="#采薇" aria-label="Permalink to &quot;采薇&quot;">​</a></h1><p><strong>《诗经·小雅》</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>采薇采薇，薇亦作止。曰归曰归，岁亦莫止。靡室靡家，猃狁之故。不遑启居，猃狁之故。 采薇采薇，薇亦柔止。曰归曰归，心亦忧止。忧心烈烈，载饥载渴。我戍未定，靡使归聘。 采薇采薇，薇亦刚止。曰归曰归，岁亦阳止。王事靡盬，不遑启处。忧心孔疚，我行不来！ 彼尔维何？维常之华。彼路斯何？君子之车。戎车既驾，四牡业业。岂敢定居？一月三捷。 驾彼四牡，四牡骙骙。君子所依，小人所腓。四牡翼翼，象弭鱼服。岂不日戒？猃狁孔棘！ 昔我往矣，杨柳依依。今我来思，雨雪霏霏。行道迟迟，载渴载饥。我心伤悲，莫知我哀！</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>薇：野豌豆苗，可食用</li><li>作：初生</li><li>止：语气词</li><li>曰：说，言</li><li>莫：同&quot;暮&quot;，年末</li><li>靡：无</li><li>猃狁：古代北方少数民族</li><li>不遑：无暇</li><li>启居：跪坐和安坐，指安居</li><li>柔：柔嫩</li><li>烈烈：炽烈，形容忧心如焚</li><li>载：又</li><li>戍：驻守</li><li>聘：问候</li><li>刚：坚硬，指薇菜茎老</li><li>阳：农历十月</li><li>盬：止息</li><li>启处：同&quot;启居&quot;</li><li>孔：很，非常</li><li>疚：痛苦</li><li>来：归来</li><li>尔：同&quot;薾&quot;，花盛开的样子</li><li>常：棠棣树</li><li>路：同&quot;辂&quot;，大车</li><li>君子：指将帅</li><li>戎车：兵车</li><li>牡：雄马</li><li>业业：高大健壮的样子</li><li>骙骙：强壮的样子</li><li>依：乘坐</li><li>小人：指士兵</li><li>腓：隐蔽，依托</li><li>翼翼：整齐的样子</li><li>象弭：象牙装饰的弓</li><li>鱼服：鱼皮做的箭袋</li><li>日戒：每日警戒</li><li>棘：同&quot;急&quot;，紧急</li><li>依依：轻柔摇曳的样子</li><li>思：语气词</li><li>霏霏：大雪纷飞的样子</li><li>迟迟：缓慢</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>采薇菜呀采薇菜，薇菜刚刚冒出芽。说回家呀说回家，一年又快过完啦。没有家呀没有室，都是因为猃狁来侵犯。无法安居来休息，都是因为猃狁来侵犯。 采薇菜呀采薇菜，薇菜鲜嫩正可采。说回家呀说回家，心中忧愁多悲哀。忧心如焚难忍受，又饥又渴真难耐。我的驻地不固定，无法托人带信来。 采薇菜呀采薇菜，薇菜茎老叶已硬。说回家呀说回家，十月又到小阳春。王事繁忙无休止，无法安居来歇身。心中痛苦非常深，我的归期无踪影！ 那盛开的是什么花？是棠棣花在绽放。那高大的是什么车？是将帅乘坐的战车。兵车已经驾好了，四匹雄马真雄壮。怎敢安然住下来？一月之中三回胜仗！ 驾起那四匹雄马，四匹马儿多强壮。将帅乘车来指挥，士兵依托车下藏。四匹马儿排整齐，象牙弓配鱼皮囊。怎能不天天警戒？猃狁来犯太紧急！ 回想当年出征时，杨柳依依随风舞。如今归来路途中，大雪纷飞漫天舞。道路泥泞行走慢，又渴又饥真辛苦。我的心中多伤悲，有谁知道我的苦！</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《采薇》是《诗经·小雅》中的名篇，是一首描写戍边战士生活的诗歌。全诗六章，前三章以&quot;采薇&quot;起兴，反复咏叹战士久戍不归的忧愁与思乡之情；四、五章描写军队的生活和战斗的紧张；末章&quot;昔我往矣，杨柳依依。今我来思，雨雪霏霏&quot;更是千古名句，以乐景写哀，以哀景写乐，倍增其哀乐，被誉为《诗经》中最佳诗句之一。全诗通过今昔对比，深刻表现了战争给人民带来的苦难，以及战士们对和平生活的渴望，具有强烈的艺术感染力。</p><hr><h2 id="关于《诗经》" tabindex="-1">关于《诗经》 <a class="header-anchor" href="#关于《诗经》" aria-label="Permalink to &quot;关于《诗经》&quot;">​</a></h2><blockquote><p>《诗经》是中国古代诗歌开端，最早的一部诗歌总集，收集了西周初年至春秋中叶的诗歌305篇，又称“诗三百”。作者多不可考，相传为孔子编订。</p><p><a href="/books/shici/shijing.html">查看诗经详情 →</a></p></blockquote>',13)),s(l)])}const b=a(n,[["render",h]]);export{m as __pageData,b as default};
